import logging


logger = logging.getLogger(__name__)


class PhysicalTable:
    """Represents a physical table extracted by Camelot."""

    def __init__(self, camelot_table):
        self._table = camelot_table
        self._data_start_index = 0
        self._headers = None
        self._headers_extras = []

    @property
    def table(self):
        # Return the original Camelot table.
        return self._table

    @property
    def cells(self):
        # Return the cell structure generated by Camelot.
        return self._table.cells

    @property
    def data(self):
        # Return the extracted table data.
        return self._table.data

    @property
    def page(self):
        # Return the PDF page number containing this table.
        return self._table.page

    @property
    def row_count(self):
        # Return the number of extracted rows.
        return len(self.data)

    @property
    def column_count(self):
        # Derive the column count from the first row.
        return len(self.data[0]) if self.data else 0

    @property
    def data_start_index(self):
        # Return the index where actual data rows begin.
        return self._data_start_index

    @property
    def headers(self):
        """Extract headers lazily and cache the result."""

        if self._headers is None:
            self._headers = self.get_headers()

            logger.debug(
                "Headers extracted | Page: %s | Headers: %s | "
                "Header extras: %s | Data start index: %s",
                self.page,
                self._headers,
                self._headers_extras,
                self._data_start_index,
            )

        return self._headers

    @property
    def headers_extras(self):
        # Return additional header information, such as full-width headings.
        return self._headers_extras

    @staticmethod
    def get_header_spans(row: list) -> list[int]:
        # Determine how many columns each cell spans using Camelot cell boundaries.
        spans, width = [], 1

        for cell in row:
            width += not cell.right

            if cell.right:
                spans.append(width)
                width = 1

        return spans

    @staticmethod
    def normalize_text(text: str) -> str:
        # Replace line breaks with spaces and remove surrounding whitespace.
        return text.replace('\n', ' ').strip()

    @staticmethod
    def normalize_headers(headers: list[str]) -> list[str]:
        # Normalize each extracted header.
        return [
            PhysicalTable.normalize_text(header)
            for header in headers
        ]

    @staticmethod
    def expand_headers(
        headers: list[str],
        spans: list[int],
    ) -> list[str]:
        # Expand merged header cells to match the actual column count.
        expanded_headers = []
        index = 0

        for span in spans:
            expanded_headers.extend([headers[index]] * span)
            index += span

        return expanded_headers

    def get_headers(self) -> list[str]:

        # A single-row table contains data, not headers.
        if self.row_count == 1:
            return []

        # Initialize an empty header for every column.
        headers = [""] * self.column_count

        for index, (cell_row, data_row) in enumerate(
            zip(self.cells, self.data)
        ):
            # Data starts immediately after the current header row.
            self._data_start_index = index + 1

            spans = self.get_header_spans(cell_row)

            # Skip a row whose header spans all columns.
            if len(spans) == 1:
                if headers_extra := self.normalize_text(data_row[0]):
                    self._headers_extras.append(headers_extra)

                continue

            # Expand merged cells so each column gets its corresponding header.
            expanded_headers = self.expand_headers(data_row, spans)

            # Combine this row with previously discovered header levels.
            headers = [
                f"{a} {b}".strip()
                for a, b in zip(headers, expanded_headers)
            ]

            # Stop once a clean single-level header is encountered.
            if len(spans) == sum(spans) == self.column_count:
                break

        return self.normalize_headers(headers)
